// ---------- Даты (календарные дни в US_TZ) ----------

export type Ymd = { y: number; m: number; d: number }; // m: 1..12

export function todayUs(now = new Date()): Ymd {
  const [y, m, d] = new Intl.DateTimeFormat('en-CA', { timeZone: US_TZ, year: 'numeric', month: '2-digit', day: '2-digit' })
    .format(now).split('-').map(Number);
  return { y, m, d };
}

export function addDays(base: Ymd, days: number): Ymd {
  const t = new Date(Date.UTC(base.y, base.m - 1, base.d + days));
  return { y: t.getUTCFullYear(), m: t.getUTCMonth() + 1, d: t.getUTCDate() };
}

export function dayDiff(target: Ymd, base: Ymd): number {
  return Math.round((Date.UTC(target.y, target.m - 1, target.d) - Date.UTC(base.y, base.m - 1, base.d)) / 86_400_000);
}

/** «Oct 18» — как кнопка даты в New Job. */
export const shortEn = (x: Ymd) => `${MONTHS_EN[x.m - 1]} ${x.d}`;
/** «October 2026» — заголовок месяца в календаре (EN). */
export const captionEn = (x: Ymd) => `${MONTHS_EN_LONG[x.m - 1]} ${x.y}`;

/**
 * Ожидаемая относительная метка в колонке Scheduled (комментарий программиста к #6605fa).
 * Дни — точная строка; от 30 дней — месяцы, от 365 — годы: точное округление не задано, проверяется форма и направление.
 * // годы не проверены вручную (заметка 18.10) — форма по аналогии.
 */
export function expectedRelative(diff: number, lang: Lang): RegExp {
  const n = Math.abs(diff);
  if (lang === 'en') {
    if (diff === 0) return /^Today$/;
    if (diff === 1) return /^Tomorrow$/;
    if (diff === -1) return /^Yesterday$/;
    if (n < 30) return diff > 0 ? new RegExp(`^In ${n} days$`) : new RegExp(`^${n} days ago$`);
    if (n < 365) return diff > 0 ? /^(Next month|In \d+ months)$/ : /^(Last month|\d+ months ago)$/;
    return diff > 0 ? /^(Next year|In \d+ years)$/ : /^(Last year|\d+ years ago)$/;
  }
  if (diff === 0) return /^היום$/;
  if (diff === 1) return /^מחר$/;
  if (diff === -1) return /^אתמול$/;
  const dir = diff > 0 ? 'בעוד' : 'לפני';
  if (n < 30) return new RegExp(`^${dir} (${n} ימים${n === 2 ? '|יומיים' : ''})$`);
  if (n < 365) return new RegExp(`^${dir} (חודש|חודשיים|\\d+ חודשים)$`);
  return new RegExp(`^${dir} (שנה|שנתיים|\\d+ שנים)$`);
}

export type ScheduledCell = { kind: 'none' } | { kind: 'date'; date: Ymd; label: string } | { kind: 'other'; text: string };

/** Разбор ячейки Scheduled: EN «Oct 17, 2026 Yesterday», HE «17 אוקטובר 2026 אתמול», либо «Not scheduled». */
export function parseScheduled(raw: string, lang: Lang): ScheduledCell {
  const text = raw.replace(/\s+/g, ' ').trim();
  if (text === T[lang].notScheduled) return { kind: 'none' };
  if (lang === 'en') {
    const m = text.match(/^([A-Z][a-z]{2}) (\d{1,2}), (\d{4}) (.+)$/);
    if (m && MONTHS_EN.includes(m[1])) return { kind: 'date', date: { y: +m[3], m: MONTHS_EN.indexOf(m[1]) + 1, d: +m[2] }, label: m[4].trim() };
  } else {
    const m = text.match(/^(\d{1,2}) (\S+) (\d{4}) (.+)$/);
    if (m && MONTHS_HE.includes(m[2])) return { kind: 'date', date: { y: +m[3], m: MONTHS_HE.indexOf(m[2]) + 1, d: +m[1] }, label: m[4].trim() };
  }
  return { kind: 'other', text };
}

// ---------- Список Jobs ----------

/** /jobs → список загружен. */
export async function openJobsList(page: Page) {
  await page.goto('/jobs');
  await expect(page.locator('main')).toContainText(/JOB-\s*\d{4}/, { timeout: 30_000 });
}

/** Номер колонки по заголовку (th / columnheader). */
export async function columnIndex(page: Page, header: string): Promise<number> {
  const headers = page.locator('main thead th, main [role="columnheader"]');
  await expect(headers.filter({ hasText: header }).first()).toBeVisible();
  const texts = (await headers.allInnerTexts()).map((t) => t.trim());
  const idx = texts.findIndex((t) => t === header);
  expect(idx, `колонка «${header}» среди: ${texts.join(' | ')}`).toBeGreaterThanOrEqual(0);
  return idx;
}

export async function scheduledCellText(page: Page, row: Locator, lang: Lang): Promise<string> {
  const idx = await columnIndex(page, T[lang].scheduled);
  return (await row.locator('td, [role="cell"]').nth(idx).innerText()).trim();
}

/** Все строки текущей вкладки списка: код работы + текст ячейки Scheduled. */
export async function allScheduledCells(page: Page, lang: Lang): Promise<{ job: string; text: string }[]> {
  const idx = await columnIndex(page, T[lang].scheduled);
  const rows = page.locator('main tbody tr').filter({ hasText: /JOB-\s*\d{4}/ });
  const n = await rows.count();
  const out: { job: string; text: string }[] = [];
  for (let i = 0; i < n; i++) {
    const row = rows.nth(i);
    const job = ((await row.innerText()).match(/JOB-\s*(\d{4})/) ?? ['', '????'])[1];
    out.push({ job: `JOB-${job}`, text: (await row.locator('td, [role="cell"]').nth(idx).innerText()).trim() });
  }
  return out;
}

// ---------- Календарь ----------

/** Кнопка даты (New Job: «Oct 18»; Job Details — «Oct 18, 2026» или похожий; пусто — «Pick a date»). */
export function dateButton(page: Page): Locator {
  return page.getByRole('button', {
    name: /^\s*(Pick a date|בחר תאריך|[A-Z][a-z]+ \d{1,2}(st|nd|rd|th)?(, \d{4})?)\s*$/,
  }).first();
}

/** Открытый календарь (поповер с сеткой дней). */
export function calendar(page: Page): Locator {
  return page.locator('[role="dialog"], [data-radix-popper-content-wrapper]').filter({ has: page.getByRole('grid') }).last();
}

export async function openCalendar(page: Page): Promise<Locator> {
  await dateButton(page).click();
  const cal = calendar(page);
  await expect(cal).toBeVisible();
  return cal;
}

/** Выбранный день в открытом календаре. */
export function selectedDay(cal: Locator): Locator {
  return cal.locator('[aria-selected="true"], [data-selected="true"], [data-selected-single="true"], .rdp-day_selected').first();
}

/** Перейти к месяцу target (кнопки предыдущего/следующего месяца) и нажать день. */
export async function pickDate(page: Page, target: Ymd) {
  const cal = await openCalendar(page);
  const caption = captionEn(target);
  for (let i = 0; i < 24 && !(await cal.getByText(caption, { exact: true }).isVisible()); i++) {
    const shown = (await cal.innerText()).match(/(January|February|March|April|May|June|July|August|September|October|November|December) (\d{4})/);
    expect(shown, 'заголовок месяца в календаре').not.toBeNull();
    const shownIdx = Number(shown![2]) * 12 + MONTHS_EN_LONG.indexOf(shown![1]);
    const targetIdx = target.y * 12 + target.m - 1;
    await cal.getByRole('button', { name: targetIdx > shownIdx ? /next/i : /prev/i }).first().click();
  }
  await expect(cal.getByText(caption, { exact: true })).toBeVisible();
  // День d: в сетке могут быть дни соседних месяцев (в начале — 23..31 прошлого, в конце — 1..6 следующего).
  const cells = cal.getByRole('gridcell').filter({ hasText: new RegExp(`^\\s*${target.d}\\s*$`) });
  const cell = target.d < 15 ? cells.first() : cells.last();
  const btn = cell.getByRole('button');
  await ((await btn.count()) ? btn.first() : cell).click();
  if (await cal.isVisible()) await page.keyboard.press('Escape');
}

// ---------- Создание / уборка работы ----------

/** New Job (EN): клиент QA-quota client, Repair, описание = title, без техника; дата — сегодня или offsetDays. Возвращает URL и код. */
export async function createQaJob(page: Page, title: string, offsetDays?: number): Promise<{ url: string; code: string }> {
  await openNewJob(page, 'en');
  const client = page.getByLabel('Client Name *');
  await client.pressSequentially('QA-quota', { delay: 20 });
  await page.getByRole('button').filter({ hasText: QA_CLIENT }).first().click();
  await expect(client).toHaveValue(QA_CLIENT);
  await expect(page.getByRole('textbox', { name: /^Address/ })).not.toHaveValue('');
  await page.getByRole('combobox').filter({ hasText: 'Select job type' }).click();
  await page.getByRole('option', { name: 'Repair', exact: true }).click();
  await page.getByLabel('Job Description').fill(title);
  if (offsetDays !== undefined && offsetDays !== 0) {
    const target = addDays(todayUs(), offsetDays);
    await pickDate(page, target);
    await expect(dateButton(page)).toHaveText(new RegExp(`^\\s*${shortEn(target)}\\b`));
  }
  await page.getByRole('button', { name: 'Create Job', exact: true }).click();
  await page.waitForURL(/\/JobDetail\?id=/, { timeout: 30_000 });
  const url = page.url().replace(/&tab=items/, '');
  const code = ((await page.getByText(/^#JOB-\d+$/).first().innerText()).trim()).slice(1);
  return { url, code };
}

/** Уборка: работа → Cancelled (EN-интерфейс). Ошибки уборки не скрывают ошибку теста — только логируются. */
export async function cancelJobs(page: Page, urls: string[]) {
  if (page.isClosed()) return;
  await useLang(page, 'en');
  for (const url of urls) {
    try {
      await page.goto(url);
      await setJobStatus(page, 'Cancelled');
    } catch (e) {
      console.warn(`[cleanup] не удалось отменить ${url}: ${(e as Error).message}`);
    }
  }
}

// ---------- Геометрия (RTL) ----------

export async function centerX(loc: Locator): Promise<number> {
  await expect(loc).toBeVisible();
  const box = await loc.boundingBox();
  expect(box, 'элемент имеет размеры').not.toBeNull();
  return box!.x + box!.width / 2;
}

/** Центры по X для списка локаторов (по порядку). */
export async function centers(locs: Locator[]): Promise<number[]> {
  const out: number[] = [];
  for (const l of locs) out.push(await centerX(l));
  return out;
}

export const isIncreasing = (xs: number[]) => xs.every((x, i) => i === 0 || x > xs[i - 1]);
export const isDecreasing = (xs: number[]) => xs.every((x, i) => i === 0 || x < xs[i - 1]);
